    aprox: ["costeAnualAproxEur"],
    pros: ["La 525ACX 2026 exprime el carnet A2 sin quedarse corta: su bicilíndrico de 494 cc entrega 48 CV y 35,3 kW, justo en el techo legal de la categoría, con 165 km/h de velocidad máxima declarada.", "No es una naked disfrazada de campera: las llantas de radios de uso mixto y la horquilla Kayaba delantera sostienen un planteamiento scrambler pensado para alternar asfalto con pistas fáciles sin cambiar de moto.", "La pantalla TFT de 7 pulgadas con control de presión de neumáticos es equipamiento difícil de encontrar en una A2 de este precio, y aquí además avisa de despresurizaciones rápidas, no solo de una presión baja cualquiera.", "El depósito de 19 litros cambia el uso diario frente a otras scrambler A2 más cortas de capacidad: menos paradas a repostar en recorridos interurbanos y más margen para escapadas de fin de semana a dúo.", "Cinco años de garantía y un precio desde 6.317 euros, marcado como aproximado en la ficha, componen el argumento de compra de esta anualidad 2026: equipamiento alto sin saltar a una cilindrada que exija el carnet A."],
    contras: ["198 kg para una moto del A2: en maniobras en parado, al moverla en el garaje o entre coches en ciudad, la 525ACX 2026 se siente más grande de lo que sugiere su cilindrada de 494 cc.", "El asiento a 840 mm deja fuera a muchos pilotos de talla baja: con esa altura, llegar con seguridad al suelo en paradas frecuentes exige probarla antes en persona, no fiarse solo de la foto.", "Sin modos de conducción en 2026: quien venga de rivales A2 con electrónica más configurable echará en falta poder suavizar la respuesta en mojado o en pistas, aquí todo queda a la mano derecha.", "Su enfoque mixto es también un compromiso: si el uso va a ser solo urbano y de naked ágil, el peso, la altura y el planteamiento scrambler juegan en contra frente a opciones más bajas y ligeras."],
    curiosidades: ["Según la ficha, el motor de 494 cc de la 525ACX es de uso exclusivo para Voge y no se suministra a otras marcas, algo poco habitual en un segmento donde compartir bloques entre fabricantes es la norma.", "La TFT de 7 pulgadas no se limita a mostrar la presión: avisa específicamente de despresurizaciones rápidas de los neumáticos, una alerta pensada para detectar un pinchazo en marcha antes de que se convierta en un susto."],
