    aprox: ["costeAnualAproxEur"],
    pros: ["Bicilíndrico en línea DOHC de 8 válvulas con refrigeración líquida: 41 CV (30,2 kW según la ficha) y 37 Nm a 7.500 rpm, con la suavidad y el sonido de un twin frente a las monocilíndricas A2, y sin necesidad de limitación porque nace por debajo del techo de 35 kW del carnet.", "Pantalla TFT a color de 5 pulgadas con dos interfaces, fondo blanco o negro, que se ajusta sola según la luz ambiental; se suman iluminación completa LED y mandos retroiluminados, un equipamiento poco habitual en una naked de 5.699 euros.", "Parte ciclo con ambición: chasis multitubular de acero, horquilla invertida, doble disco delantero tipo wave de 260 mm, disco trasero de 240 mm y ABS en las dos ruedas.", "Escape 2 en 1 con el silenciador colocado bajo el motor: además de firmar el sonido grave del bicilíndrico, baja el centro de gravedad y deja limpia la línea del colín.", "Seis años de garantía oficial incluidos en los 5.699 euros de la ficha, y transferibles al siguiente propietario si vendes la moto antes de que caduque la cobertura."],
    contras: ["186 kg en orden de marcha: es de las naked A2 de 400 cc más pesadas, unos 20 kg por encima de rivales como la Z400, y eso se nota al maniobrar en parado y al cambiar de dirección rápido.", "La horquilla invertida no admite regulación; quien quiera afinar el tren delantero a su peso o a un uso más deportivo tendrá que pasar por taller y cambiar componentes.", "Electrónica justa para 2026: más allá del ABS y la TFT no hay control de tracción, modos de conducción ni cambio rápido, ayudas que ya empiezan a verse en la competencia.", "Marca llegada a España en 2022 de la mano del Grupo Bordoy: la red comercial y de talleres sigue creciendo, y la reventa de una QJMotor usada todavía no tiene el recorrido de una japonesa equivalente."],
    curiosidades: ["El portamatrículas va fijado al basculante, no al colín: así la zaga, con forma de lágrima, queda flotando sobre la rueda trasera sin soportes visibles, un detalle más propio de naked de mayor cilindrada.", "Se vendió en dos decoraciones muy distintas: gris con el chasis pintado en verde o negro con las llantas doradas, según recogió la prensa española en su lanzamiento."],
