    aprox: ["costeAnualAproxEur"],
    pros: ["El propulsor bicilíndrico en V marca diferencias en sonido y carácter frente a los monocilíndricos habituales en esta cilindrada", "Sus 14,5 CV dejan muy poco margen hasta el límite que marca la normativa para el carnet A1", "Con 15 litros de capacidad en el depósito, esta Keeway permite olvidarse de la gasolinera durante bastantes trayectos", "También puedes pilotarla apoyándote en el permiso B, siempre que ya sumes tres años con ese carnet", "La estética tipo bobber, baja y con mucha presencia, la distingue al instante de scooters y naked de 125", "Entre su instrumentación digital y su faro con tecnología LED, el equipamiento transmite una sensación bastante actual"],
    contras: ["El desembolso inicial se sitúa por encima de lo que piden varias rivales asiáticas de idéntica cilindrada", "No es una moto ligera en su categoría y esa contundencia se nota cuando buscas agilidad en ciudad", "Quien espere ayudas electrónicas sofisticadas encontrará una propuesta sencilla, pensada más en lo esencial que en la tecnología", "Al venderla de segunda mano probablemente recuperes menos porcentaje que con marcas japonesas más asentadas", "En zonas concretas como mandos o remates cromados, la percepción de calidad queda por detrás de su aspecto general"],
    curiosidades: ["La letra final del apellido no es decorativa: señala su orientación clásica dentro de la familia RKV", "Keeway pertenece al universo del grupo QJMotor, un gigante chino que sostiene buena parte de su catálogo europeo", "Pocas 125 de estilo custom montan una arquitectura en V; ahí reside buena parte de su personalidad mecánica", "Aunque su imagen mira al ocio del fin de semana, su homologación para dos ocupantes y su etiqueta C la hacen usable a diario"],
