    pros: ["Desde 2.899 € en la ficha de 2025: la vía más barata de entrar en la familia Cromwell sin renunciar a la estética británica clásica", "Depósito de 14 litros y asiento a 770 mm según la web oficial de Brixton: planteamiento pensado para el día a día y para pilotos que empiezan", "Luces diurnas e intermitentes LED y velocímetro con tacómetro, indicador de combustible y cuentakilómetros, equipamiento confirmado en la página oficial del modelo", "Dos plazas y acceso con carnet A1, válido también con el B más tres años, con etiqueta DGT C en la ficha para moverse a diario"],
    contras: ["Con 11 CV en la ficha, en vías rápidas y con pasajero se queda justa: su terreno natural es la ciudad y las carreteras secundarias tranquilas", "Monocilíndrico refrigerado por aire con cambio de 5 velocidades: mecánica sencilla y probada, pero con poco margen para adelantar con soltura fuera de ciudad", "El precio de 2.899 € corresponde a la versión CBS; quien quiera ABS tiene que pasar a la versión de 3.099 € recogida en la ficha", "Sin ayudas electrónicas más allá del sistema de frenada elegido: no hay modos de conducción ni control de tracción en esta clásica de acceso"],
