    etiquetaDgt: "C",
    aprox: ["costeAnualAproxEur"],
    pros: ["En 2026 mantiene los 2.499 € de la EVO de 2025 pese al motor nuevo: sus rivales custom con 15 CV como la Zontes 125C o la Cyclone RA125 Plus ya superan los 3.000 € según las pruebas citadas", "El monocilíndrico de 4 válvulas entrega 12,2 CV a 9.500 rpm y 9,9 Nm a 8.000 rpm, un 28 % más que los 9,5 CV anteriores, y se nota sobre todo al estirar marchas fuera del centro urbano", "ABS de doble canal, iluminación Full LED y cuadro LCD de serie en una custom de este precio, con discos de 267 mm delante y 240 mm detrás en lugar de conformarse con frenada combinada", "Asiento a solo 730 mm y depósito de 13,5 litros con un consumo probado en torno a 2,6 l/100 km: llegar al suelo es inmediato y las paradas a repostar quedan muy espaciadas para ser una 125", "Es la Rockster clásica, no la Flat: manillar tipo cuerno de vaca, respaldo para el pasajero y llantas de radios, en negro, rojo o el tono Gilver, frente al manillar plano y más bajo de su hermana de 2.599 €"],
    contras: ["Con 12,2 CV queda lejos del límite de 15 CV del A1: una Cyclone RA125 Plus o una Zontes 125C con la potencia máxima legal la dejan atrás en incorporaciones y adelantamientos en carretera abierta", "Su geometría es de custom relajada, con llanta delantera de 18 pulgadas y ángulo de dirección generoso: en curvas cerradas no responde con la rapidez de una naked 125 y no hay que pedírselo", "Las pruebas de la versión estándar señalan dos mandos mal resueltos para algunos conductores, el pedal de freno trasero y la palanca de cambio algo elevados, un defecto que paradójicamente no aparece en la Flat", "Los amortiguadores traseros cortos se muestran secos y rebotones cuando el asfalto se rompe, algo que en la EVO 2026 sigue sin corregirse porque la parte ciclo se mantiene tal cual llegó en 2025"],
    curiosidades: ["Es el modelo más vendido de Macbor desde su nacimiento en 2017 y su diseño se desarrolla en Barcelona, aunque la fabricación se realiza en China, según cuentan SoyMotero y Motofichas en sus pruebas.", "Comparte motor, chasis y precio base con la Rockster Flat 125 EVO salvo por 100 € de diferencia: todo lo que las separa es ergonomía y estética, manillar, asiento y colores, no la mecánica."],
