    aprox: ["costeAnualAproxEur"],
    pros: ["Cambio manual de 6 marchas con embrague de verdad: el Minarelli NG de 2 tiempos y refrigeración líquida obliga a aprender a cambiar, a salir en primera y a usar el freno motor antes de dar el salto a una 125, algo que un scooter automático de carnet AM no enseña.", "Una misma base para dos usos distintos: la familia MRT 50 se ofrece en clave Enduro y en clave Supermotard, compartiendo motor y chasis de doble viga perimetral de acero, así que en 2026 la elección es de ruedas y neumáticos —taco o asfalto— y no de mecánica.", "85 kg en esta ficha y depósito de 6,3 litros: a ritmo de instituto, de pueblo o de pista fácil se mueve y se levanta tras una caída sin ayuda, y no vive pegada a la gasolinera entre semana.", "Subchasis trasero desmontable sobre el chasis perimetral de acero de alta resistencia: en una moto pensada para aprender fuera del asfalto, poder sustituir la parte trasera tras un golpe vale más que un adorno electrónico.", "Sigue en 3.406 €, el mismo importe que las fichas de la añada 2025: la 2026 no encarece la entrada a una moto de marchas fabricada en Figueres, con la carrocería afilada de la generación 2022-2026 todavía vigente."],
    contras: ["Techo legal de ciclomotor: 45 km/h en las fichas técnicas consultadas. En una nacional con tráfico a 90 se convierte en un tapón rodante y los adelantamientos, sencillamente, no existen; su sitio es la ciudad, el camino y la carretera local tranquila.", "Arranque a patada, sin botón en las fichas consultadas, y carburador en un motor de 2 tiempos: arrancar en frío exige pierna y maña, y el plan de esta ficha ya marca primera revisión a los 500 km y después cada 3.000 km o 12 meses.", "Asiento a 860 mm en las versiones Europa y Trophy documentadas: quien llegue justo de pierna a los 15 años maniobrará de puntillas en parado, justo cuando menos experiencia tiene para sujetar la moto.", "En los datos de esta ficha figura con 1 plaza: es una moto para uno solo, sin margen para llevar a nadie detrás ni para convertirla en transporte compartido entre hermanos o amigos."],
    curiosidades: ["Rieju no es una sigla técnica: sale de coser los apellidos de sus dos fundadores, RIEra y JUanola, que empezaron en Figueres fabricando accesorios de bicicleta mucho antes de hacer su primer ciclomotor.", "El apellido Minarelli del motor de esta MRT viene de lejos: Rieju acordó en 1964 fabricar motores de la marca italiana bajo licencia y lanzó con ellos la Jaca, seis décadas antes de esta 50 de 2026."],
