    etiquetaDgt: "Cero",
    aprox: ["costeAnualAproxEur"],
    pros: ["Su motor va en posición central y mueve la rueda trasera por cadena, no en el buje como en una NIU MQi GT o una Super Soco CPX: con 6,2 kW de pico oficiales acelera de 0 a 60 km/h en seis segundos y empuja hasta 95 km/h con el par disponible desde el primer giro de puño", "En la prueba española de Híbridos y Eléctricos marcó 28,19 km por kWh, unos 2,36 kWh a los 100 km: fue el scooter eléctrico más frugal de cuantos habían probado, por encima incluso del Ecooter E2 Max con 28,11 km por kWh y con menos potencia", "La batería se extrae y pesa unos 17 kg según la prueba británica de 2025, así que quien vive en un piso sin enchufe en el garaje la sube a casa o a la oficina y la deja cargando entre cuatro horas y cuatro horas y media", "Rueda delantera de 14 pulgadas y trasera de 13, batalla de 1.320 mm y asiento a 780 mm: en 2026 sigue siendo un scooter de suelo plano con hueco bajo el asiento para un casco jet con una sola batería y guantera delantera con toma USB", "Mantiene un equipamiento raro en su franja: arranque sin llave deslizando el dedo por la pantalla, control de crucero, marcha atrás, alarma antirrobo y tiras LED también en los laterales, que son su firma cuando se le ve de noche"],
    contras: ["En 2026 sigue frenando solo con CBS, sin ABS: dos discos con reparto combinado que cumplen en ciudad, pero la Horwin no ofrece el antibloqueo que ya se espera en un scooter equivalente a 125 que roza los 95 km/h", "La autonomía real queda lejos de la teórica y el cuadro no ayuda: no muestra autonomía estimada, solo porcentaje de batería, y su pantalla brillante cuesta de leer a pleno sol; en la prueba de 2025, en modo 3 por vías rápidas, la batería cayó al 15 % tras solo unos 40-48 km", "La segunda batería se paga aparte y se come el hueco bajo el asiento, así que desaparece el sitio del casco; en la prueba española de 2022 el conjunto pasaba de 4.700 a 5.600 euros, y los 200 km que se le atribuyen son la cifra teórica a 45 km/h sostenidos, no un dato de uso real", "El motor central tiene su peaje: la prueba española detectó tirones de cadena al rodar a velocidad constante entre el tráfico y Horwin España obliga a limpiar y lubricar esa cadena cada 1.500-3.000 km, un mantenimiento que sus rivales de buje o correa no piden; las suspensiones, además, son básicas y se descolocan rodando cerca de su punta"],
    curiosidades: ["El Red Dot que luce la EK3 es el de Product Design de 2021, con gala en junio de ese año en Essen, y no el de 2020 que arrastraba el texto clonado de su pareja: Horwin Europe lo sigue mostrando en la página oficial de la serie EK.", "Al apagarla, las luces no se cortan de golpe: un retardo automático las mantiene encendidas unos segundos para iluminarte el camino hasta la puerta de casa o del garaje antes de bajar del scooter, según describe la propia Horwin Europe."],
