    contras: ["Los 80 km/h de punta dejan poco margen en incorporaciones a vías rápidas", "Con 4,1 kW, las recuperaciones con pasajero o en pendiente se notan contenidas", "La ficha no publica la capacidad de la batería, un dato clave al comparar rivales", "La autonomía declarada caerá si sostienes ritmos altos durante trayectos largos", "Al ser una marca aún poco extendida aquí, conviene confirmar taller cercano antes de comprar", "No consta ABS confirmado en la ficha, detalle a valorar frente a otros scooters urbanos"],
