    pros: ["Pensada para enlazar barrios y rondas sin ir justa de carga: anuncia hasta 130 km por enchufe en su cifra declarada", "Corre de verdad fuera del casco urbano, con una punta homologada que se planta en los 105 por hora", "El empuje instantáneo entrega un pico equivalente a 13,6 CV, suficiente para moverte con soltura incluso llevando pasajero", "Lleva dos acumuladores desmontables que puedes enchufar en cualquier toma doméstica, sin depender de un garaje con punto fijo", "Circular sin restricciones te sale muy barato: luce distintivo Cero y el gasto energético de cada trayecto resulta contenido"],
