    cilindradaCc: null,
    categoria: "Scooter",
    precioDesde: 12260, // tarifa oficial España (verificado 20/10/2026)
    potenciaKw: 31,
    potenciaCv: 42,
    autonomiaKm: 130,
    autonomiaCiclo: "Declarada",
    bateriaKwh: 8.9,
    velocidadMax: 120,
    ceroCincuenta: 2.6,
    pesoKg: 231,
