    aprox: [],
    pros: ["La novedad que define a esta 2025 es poder extraer las dos baterías de 1,96 kWh cada una —3,92 kWh en total— y cargarlas en casa o en la oficina, sin depender de un garaje con enchufe propio.", "En semáforos no hay 125 eléctrica que la deje atrás: 55 Nm desde parado, 11 kW de pico y 0 a 50 km/h en 3,0 segundos, con una entrega limpia en los modos Flow y Surf.", "Con 132 kg, asiento a solo 750 mm y ruedas de 14 pulgadas delante, se mueve entre coches y se aparca en huecos donde un scooter GT ni cabe; ideal si vienes del carnet B o del A1.", "Trae detalles impropios de una urbana de acceso: marcha atrás para salir de rampas, control de tracción ASC, arranque Keyless Ride, pantalla TFT de 3,5 pulgadas y toma USB-C de serie."],
    contras: ["Los 8.400 euros aproximados la colocan muy por encima de rivales eléctricas de 125, y el paquete Highline con modo Flash y cargador de 1.500 W se paga aparte sobre el cargador de 900 W de serie.", "Los 95 km WMTC se quedan cortos fuera del centro: en pruebas reales la autonomía ronda los 80 km y cae más si abusas del modo Flash o de vías rápidas a 95 km/h.", "No hay hueco bajo el asiento para un casco integral, porque ese espacio lo ocupan las baterías; sin top case o mochila, la capacidad para recados es prácticamente nula.", "El ABS actúa solo en la rueda delantera y el monoamortiguador trasero, con solo 56 mm de recorrido, transmite los baches con sequedad, sobre todo yendo a dúo."],
    curiosidades: ["BMW la bautizó eParkourer y su diseñador, Alexander Buckan, describió el concepto de 2021 como una especie de monopatín sobre dos ruedas pensado para jóvenes que nunca habían tenido moto.", "La CE 02 x Deus Lodge, creada junto a Deus Ex Machina, lleva cuatro altavoces Marshall y una mesa de DJ plegable: no es una versión de calle al uso, sino un escaparate rodante de cultura surf y skate."],
